  'files': [
    {'name': 'SalesReports', 'size': null, 'type': 'directory', 'modifiedDate': '2023-03-20T10:15:30Z'},
    {'name': 'QuarterlyFinancials.xlsx', 'size': 31945, 'type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'modifiedDate': '2023-03-19T09:24:17Z'},
