    {'name': 'MeetingNotes.txt', 'size': 830, 'type': 'text/plain', 'modifiedDate': '2023-03-17T14:05:52Z'},
    {'name': 'Presentation.pptx', 'size': 40960, 'type': 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'modifiedDate': '2023-03-16T13:45:29Z'},
